# Instructions ----
#' This file follows the format generated by FIMS:::use_testthat_template().
#' Necessary tests include input and output (IO) correctness [IO
#' correctness], edge-case handling [Edge handling], and built-in errors and
#' warnings [Error handling]. See `?FIMS:::use_testthat_template` for more
#' information. Every test should have a @description tag, which can only span
#' one lines, that will be used in the bookdown report of the results from
#' {testthat}. This line can be more than 80 characters.

# dimensions_to_tibble ----
## Setup ----
# 30 years of data, written as the JSON output does
n_years <- 30

## IO correctness ----
test_that("dimensions_to_tibble() works with correct inputs", {
  #' @description Test that "n_years" indexes years from 1 to n_years.
  expect_equal(
    object = dimensions_to_tibble(
      list(header = list("n_years"), dimensions = list(n_years))
    ),
    expected = tibble::tibble(year_i = 1:n_years),
    # expand.grid() keeps its own attribute
    ignore_attr = "out.attrs"
  )

  #' @description Test that "n_years-1" indexes years from 2 to n_years, because the first year has no value.
  expect_equal(
    object = dimensions_to_tibble(
      list(header = list("n_years-1"), dimensions = list(n_years - 1))
    ),
    expected = tibble::tibble(year_i = 2:n_years),
    # expand.grid() keeps its own attribute
    ignore_attr = "out.attrs"
  )

  #' @description Test that "3+n_years" indexes years from -2 to n_years, so the 3 values before the first year are at or below 0.
  expect_equal(
    object = dimensions_to_tibble(
      list(header = list("3+n_years"), dimensions = list(n_years + 3))
    ),
    expected = tibble::tibble(year_i = -2:n_years),
    # expand.grid() keeps its own attribute
    ignore_attr = "out.attrs"
  )
})

## Edge handling ----
test_that("dimensions_to_tibble() returns correct outputs for edge cases", {
  #' @description Test that a prefix only shifts its own dimension when combined with another dimension.
  expect_equal(
    object = dimensions_to_tibble(
      list(header = list("n_ages", "2+n_years"), dimensions = list(3, 5))
    ),
    expected = expand.grid(age_i = 1:3, year_i = -1:3) |>
      tibble::as_tibble() |>
      dplyr::arrange(age_i, year_i)
  )
})
